package org.novasos.healthysv2.pharmacy;
import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
interface PrescriptionRepository extends JpaRepository<Prescription,UUID>{@Query("select p from Prescription p where (:patient is null or p.patientId=:patient) and (:organization is null or p.organizationId=:organization) and (:status is null or p.status=:status) order by p.prescribedAt desc")Page<Prescription>search(@Param("patient")UUID patient,@Param("organization")UUID organization,@Param("status")String status,Pageable pageable);}
interface MedicationStockRepository extends JpaRepository<MedicationStock,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select s from MedicationStock s where s.organizationId=:organization and s.medicationId=:medication and s.batch=:batch")Optional<MedicationStock>lock(@Param("organization")UUID organization,@Param("medication")UUID medication,@Param("batch")String batch);@Query("select s from MedicationStock s where (:organization is null or s.organizationId=:organization) and (:medication is null or s.medicationId=:medication) order by s.expirationDate")List<MedicationStock>search(@Param("organization")UUID organization,@Param("medication")UUID medication);}
